<?php
declare(strict_types=1); require dirname(__DIR__,2).'/app/bootstrap.php'; $user=Auth::requireLogin(); Auth::requirePermission('bookings.manage'); $pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$allowed=['reviewing','confirmed','rejected','cancelled','new'];if($id<1||!in_array($status,$allowed,true))$error='طلب غير صالح.';else try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT b.*,t.seats_total,t.status trip_status FROM bookings b JOIN trips t ON t.id=b.trip_id WHERE b.id=? FOR UPDATE');$q->execute([$id]);$b=$q->fetch();if(!$b)throw new RuntimeException('الحجز غير موجود.');if($status==='confirmed' && $b['status']!=='confirmed'){$t=$pdo->prepare('SELECT seats_total,status FROM trips WHERE id=? FOR UPDATE');$t->execute([$b['trip_id']]);$trip=$t->fetch();$sum=$pdo->prepare("SELECT COALESCE(SUM(passengers_count),0) FROM bookings WHERE trip_id=? AND status='confirmed'");$sum->execute([$b['trip_id']]);$available=(int)$trip['seats_total']-(int)$sum->fetchColumn();if($trip['status']!=='available'||$available<(int)$b['passengers_count'])throw new RuntimeException('لا توجد مقاعد كافية لتأكيد هذا الحجز.');}$pdo->prepare('UPDATE bookings SET status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare('INSERT INTO activity_logs(user_id,action_key,entity_type,entity_id,description,ip_address) VALUES(?,?,?,?,?,?)')->execute([$user['id'],'booking.status_changed','booking',$id,'تغيير حالة الحجز إلى '.$status,$_SERVER['REMOTE_ADDR']??null]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$rows=$pdo->query('SELECT b.id,b.reference_code,b.status,b.passengers_count,b.created_at,c.full_name,c.phone,t.departure_at,o.name_ar origin_name,d.name_ar destination_name,co.name company_name FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN trips t ON t.id=b.trip_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id JOIN companies co ON co.id=t.company_id ORDER BY b.id DESC LIMIT 300')->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الحجوزات | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"><style>.wrap{padding:25px;overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}td,th{text-align:right;padding:12px;border-bottom:1px solid #eee;font-size:13px}form.inline{display:flex;gap:5px}select{margin:0;padding:7px}</style></head><body><header class="site-header"><a class="brand" href="/admin/index.php"><span class="brand-mark">م</span><b>إدارة الحجوزات</b></a><a href="/admin/index.php">لوحة التحكم</a></header><main class="wrap"><h1>طلبات الحجز</h1><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><div class="panel"><table><thead><tr><th>المرجع</th><th>العميل</th><th>الهاتف</th><th>الرحلة</th><th>المقاعد</th><th>الحالة</th><th>تحديث الحالة</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reference_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['origin_name'].' - '.$r['destination_name'].' / '.$r['company_name'])?></td><td><?=(int)$r['passengers_count']?></td><td><?=e($r['status'])?></td><td><form class="inline" method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><?php foreach(['new','reviewing','confirmed','rejected','cancelled'] as $s):?><option value="<?=e($s)?>" <?=$r['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn btn-primary" type="submit">حفظ</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">لا توجد طلبات.</td></tr><?php endif;?></tbody></table></div></main></body></html>